  --shadow-sm: 0 4px 16px rgba(0, 0, 0, 0.35);
  --maxw: 1240px;
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Fraunces", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--text);
  background-color: var(--bg);
  background-image:
    radial-gradient(900px 500px at 85% -10%, rgba(214, 178, 122, 0.08), transparent 60%),
    radial-gradient(700px 400px at -10% 30%, rgba(120, 110, 200, 0.06), transparent 60%);
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }
a:focus-visible, button:focus-visible, input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

h1, h2, h3 { font-family: var(--font-display); font-weight: 500; letter-spacing: -0.01em; line-height: 1.15; margin: 0; }
h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); }
h3 { font-size: 1.2rem; }
p { margin: 0; color: var(--text-muted); }

.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding: 0 24px; }

.visually-hidden, .skip-link {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.skip-link:focus {
  position: fixed; top: 12px; left: 12px; width: auto; height: auto; padding: 10px 14px;
  background: var(--accent); color: #1a140a; font-weight: 600; z-index: 1000; clip: auto; border-radius: 6px;
}

/* HEADER */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background-color: rgba(11, 11, 13, 0.85);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 16px 24px; }
.brand { display: inline-flex; align-items: center; gap: 10px; font-family: var(--font-display); font-size: 1.15rem; letter-spacing: 0.02em; }
.brand-mark { color: var(--accent); font-size: 1.1rem; }
.brand-name { color: var(--text); font-weight: 600; }
.brand-amp { color: var(--accent); margin: 0 2px; }

.primary-nav ul { display: flex; gap: 28px; list-style: none; padding: 0; margin: 0; }
.primary-nav a {
  font-size: 0.92rem; color: var(--text-muted); padding: 6px 0; position: relative; transition: color 0.2s;
}
.primary-nav a:hover { color: var(--text); }
.primary-nav a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -2px; height: 1px;
  background: var(--accent); transform: scaleX(0); transform-origin: left;
  transition: transform 0.25s ease;
}
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions { display: flex; align-items: center; gap: 6px; }
.icon-btn {
  position: relative; width: 40px; height: 40px; display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 1px solid transparent; border-radius: 999px; color: var(--text-muted);
  cursor: pointer; transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); border-color: var(--border); }
.cart-count {
  position: absolute; top: 2px; right: 2px; min-width: 18px; height: 18px; padding: 0 5px;
  background: var(--accent); color: #1a140a; font-size: 11px; font-weight: 700;
  border-radius: 999px; display: inline-flex; align-items: center; justify-content: center;
}

.announcement {
  text-align: center; font-size: 0.82rem; padding: 8px 16px;
  background: var(--bg-elev); color: var(--text-muted); border-top: 1px solid var(--border);
}
.announcement strong { color: var(--accent); font-weight: 600; }

/* HERO */
.hero { padding: 72px 0 100px; position: relative; overflow: hidden; }
.hero-inner { display: grid; grid-template-columns: 1.1fr 1fr; gap: 64px; align-items: center; }
.eyebrow {
  font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.18em;
  color: var(--accent); margin: 0 0 14px; font-weight: 600;
}
.accent { color: var(--accent); font-style: italic; }
.hero-lede { font-size: 1.1rem; max-width: 48ch; margin: 22px 0 32px; color: var(--text-muted); }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 48px; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 14px 24px; font-size: 0.95rem; font-weight: 500; font-family: inherit;
  border-radius: 999px; border: 1px solid transparent; cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.15s;
}
.btn:active { transform: translateY(1px); }
.btn-sm { padding: 10px 18px; font-size: 0.88rem; }
.btn-primary { background: var(--accent); color: #1a140a; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-ghost { background: transparent; color: var(--text); border-color: var(--border-strong); }
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-dim); }

.hero-meta {
  display: grid; grid-template-columns: repeat(3, auto); gap: 36px;
  margin: 0; padding: 24px 0 0; border-top: 1px solid var(--border);
}
.hero-meta div { display: flex; flex-direction: column; gap: 4px; }
.hero-meta dt { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.14em; color: var(--text-dim); }
.hero-meta dd { margin: 0; font-size: 0.95rem; color: var(--text); font-weight: 500; }

/* HERO VISUAL */
.hero-visual { position: relative; height: 540px; }
.hero-card {
  position: absolute; border-radius: var(--radius-lg); overflow: hidden;
  box-shadow: var(--shadow); border: 1px solid var(--border);
  background: var(--bg-elev);
}
.hero-card--main { top: 0; right: 0; width: 78%; height: 78%; }
.hero-card--sub { bottom: 0; left: 0; width: 52%; height: 48%; }
.hero-card .badge {
  position: absolute; top: 16px; left: 16px; z-index: 2;
  font-size: 0.72rem; padding: 6px 12px; background: rgba(11,11,13,0.7); color: var(--accent);
  border: 1px solid var(--border-strong); border-radius: 999px; backdrop-filter: blur(6px);
  letter-spacing: 0.08em; text-transform: uppercase; font-weight: 600;
}
.hero-art { width: 100%; height: 100%; }
.hero-art--1 {
  background:
    radial-gradient(circle at 70% 20%, rgba(214,178,122,0.35), transparent 50%),
    linear-gradient(135deg, #2a2620 0%, #1a1814 50%, #0e0c0a 100%);
  position: relative;
}
.hero-art--1::before {
  content: ""; position: absolute; inset: 0;
  background: repeating-linear-gradient(45deg, transparent 0 14px, rgba(255,255,255,0.02) 14px 15px);
}
.hero-art--2 {
  background:
    radial-gradient(circle at 30% 70%, rgba(120,110,200,0.25), transparent 60%),
    linear-gradient(160deg, #20202a 0%, #15151c 100%);
}
.hero-glow {
  position: absolute; top: 30%; right: -10%; width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(214,178,122,0.18) 0%, transparent 70%);
  filter: blur(40px); z-index: -1; pointer-events: none;
}

/* VALUES */
.values { padding: 36px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); background: var(--bg-elev); }
.values-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.value { display: flex; flex-direction: column; gap: 6px; }
.value-icon { color: var(--accent); font-size: 1.4rem; }
.value h2 { font-size: 1.05rem; font-family: var(--font-sans); font-weight: 600; letter-spacing: 0; }
.value p { font-size: 0.92rem; }

/* SECTION */
.section { padding: 96px 0; }
.section--alt { background: linear-gradient(180deg, transparent, rgba(255,255,255,0.015) 50%, transparent); }
.section-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 24px;
  margin-bottom: 40px; flex-wrap: wrap;
}
.section-aside { color: var(--text-muted); font-size: 0.9rem; }
.countdown {
  font-variant-numeric: tabular-nums; color: var(--accent); font-weight: 600;
  margin-left: 4px;
}
.section-controls { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  background: transparent; color: var(--text-muted); border: 1px solid var(--border);
  padding: 8px 16px; border-radius: 999px; font-size: 0.85rem; cursor: pointer;
  font-family: inherit; transition: all 0.2s;
}
.chip:hover { color: var(--text); border-color: var(--border-strong); }
.chip.is-active { background: var(--accent-soft); color: var(--accent); border-color: var(--accent); }

/* PRODUCT GRID */
.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;
}
.product {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); overflow: hidden;
  transition: border-color 0.25s, transform 0.25s, box-shadow 0.25s;
  display: flex; flex-direction: column;
}
.product:hover { border-color: var(--border-strong); transform: translateY(-2px); box-shadow: var(--shadow-sm); }
.product-media {
  position: relative; aspect-ratio: 4/5; overflow: hidden;
}
.product-art { position: absolute; inset: 0; }
.product-tag {
  position: absolute; top: 12px; left: 12px;
  font-size: 0.7rem; padding: 5px 10px; border-radius: 999px;
  background: rgba(11,11,13,0.7); color: var(--text); backdrop-filter: blur(6px);
  border: 1px solid var(--border-strong);
  letter-spacing: 0.06em; text-transform: uppercase; font-weight: 600;
}
.product-tag--sale { color: var(--accent); border-color: var(--accent); }
.product-tag--new { color: var(--success); border-color: rgba(143,209,158,0.4); }
.wishlist {
  position: absolute; top: 12px; right: 12px; width: 36px; height: 36px;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(11,11,13,0.7); border: 1px solid var(--border-strong);
  border-radius: 999px; color: var(--text-muted); cursor: pointer;
  backdrop-filter: blur(6px); transition: color 0.2s, background 0.2s;
}
.wishlist:hover { color: var(--accent); }
.wishlist[aria-pressed="true"] { color: var(--accent); }

.product-body { padding: 16px 18px 18px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.product-cat { font-size: 0.72rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.12em; }
.product-name { font-size: 1rem; font-family: var(--font-sans); font-weight: 500; color: var(--text); margin: 0; }
.product-price { display: flex; align-items: baseline; gap: 8px; margin-top: auto; }
.price { color: var(--text); font-weight: 600; font-size: 1rem; }
.price--was { color: var(--text-dim); text-decoration: line-through; font-weight: 400; font-size: 0.88rem; }
.add-btn {
  margin-top: 10px; background: var(--bg-elev-2); color: var(--text);
  border: 1px solid var(--border); padding: 10px 14px; border-radius: var(--radius-sm);
  font-size: 0.85rem; font-family: inherit; cursor: pointer; transition: all 0.2s;
}
.add-btn:hover { background: var(--accent); color: #1a140a; border-color: var(--accent); }

/* DEALS */
.deals-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: minmax(220px, auto);
  gap: 20px;
}
.deal {
  position: relative; border-radius: var(--radius); overflow: hidden;
  border: 1px solid var(--border); background: var(--surface);
  display: flex; flex-direction: column; min-height: 280px;
}
.deal--feature { grid-column: span 2; grid-row: span 2; }
.deal--wide { grid-column: span 2; }
.deal-art { position: absolute; inset: 0; z-index: 0; }
.deal-art--1 {
  background:
    radial-gradient(circle at 75% 20%, rgba(214,178,122,0.4), transparent 55%),
    linear-gradient(135deg, #1f1c18 0%, #0c0a08 100%);
}
.deal-art--1::after {
  content: ""; position: absolute; inset: 0;
  background: repeating-linear-gradient(135deg, transparent 0 20px, rgba(255,255,255,0.025) 20px 21px);
}
.deal-art--2 { background: linear-gradient(160deg, #1c1c25 0%, #0e0e14 100%); }
.deal-art--3 { background: linear-gradient(160deg, #221a1a 0%, #0f0a0a 100%); }
.deal-art--4 {
  background:
    radial-gradient(circle at 20% 80%, rgba(120,110,200,0.3), transparent 55%),
    linear-gradient(120deg, #18182a 0%, #0a0a14 100%);
}
.deal-body {
  position: relative; z-index: 1; padding: 28px;
  margin-top: auto; display: flex; flex-direction: column; gap: 10px; align-items: flex-start;
  background: linear-gradient(0deg, rgba(11,11,13,0.85) 0%, rgba(11,11,13,0.4) 70%, transparent 100%);
}
.deal--feature .deal-body { padding: 36px; gap: 14px; }
.deal h3 { font-size: 1.4rem; }
.deal--feature h3 { font-size: 2rem; }
.deal p { max-width: 42ch; font-size: 0.95rem; }
.badge {
  display: inline-block; font-size: 0.72rem; padding: 6px 12px;
  background: var(--bg-elev-2); color: var(--text); border: 1px solid var(--border-strong);
  border-radius: 999px; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 600;
}
.badge--accent { background: var(--accent-soft); color: var(--accent); border-color: var(--accent); }

.link-arrow {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--accent); font-weight: 500; font-size: 0.92rem;
  transition: gap 0.2s;
}
.link-arrow:hover { gap: 10px; color: var(--accent-hover); }

/* EDITORIAL */
.editorial-grid {
  display: grid; grid-template-columns: 1.6fr 1fr 1fr; gap: 24px;
}
.story { border-radius: var(--radius); overflow: hidden; background: var(--surface); border: 1px solid var(--border); transition: border-color 0.25s, transform 0.25s; }
.story:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.story--feature { grid-row: span 2; }
.story-link { display: flex; flex-direction: column; height: 100%; }
.story-art { aspect-ratio: 16/10; }
.story--feature .story-art { aspect-ratio: 4/5; }
.story-art--1 { background: radial-gradient(circle at 30% 30%, rgba(214,178,122,0.3), transparent 60%), linear-gradient(160deg, #1f1c18, #0d0c0a); }
.story-art--2 { background: linear-gradient(135deg, #1a1a22, #0c0c12); }
.story-art--3 { background: radial-gradient(circle at 70% 60%, rgba(143,209,158,0.18), transparent 60%), linear-gradient(160deg, #161e18, #0a0e0b); }
.story-art--4 { background: linear-gradient(160deg, #221a1a, #100a0a); }
.story-body { padding: 22px 24px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.story-meta { font-size: 0.78rem; color: var(--text-dim); }
.story-tag { color: var(--accent); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; font-size: 0.72rem; }
.story h3 { font-size: 1.1rem; }
.story--feature h3 { font-size: 1.6rem; }
.story-author { margin-top: auto; font-size: 0.82rem; color: var(--text-dim); padding-top: 10px; }

/* NEWSLETTER */
.newsletter { padding: 96px 0; border-top: 1px solid var(--border); background: var(--bg-elev); }
.newsletter-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
}
.newsletter h2 { margin-bottom: 16px; }
.newsletter-form {
  display: grid; grid-template-columns: 1fr auto; gap: 12px;
  background: var(--bg); padding: 10px; border-radius: 999px; border: 1px solid var(--border);
}
.newsletter-form input {
  background: transparent; border: 0; color: var(--text); font: inherit; padding: 10px 18px;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form input:focus { outline: none; }
.newsletter-form .btn { padding: 12px 24px; }
.form-status {
  grid-column: 1 / -1; padding: 0 18px; font-size: 0.85rem; min-height: 1.1em;
}
.form-status.is-success { color: var(--success); }
.form-status.is-error { color: var(--danger); }

/* FOOTER */
.site-footer { background: var(--bg); border-top: 1px solid var(--border); padding: 64px 0 24px; }
.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 48px; padding-bottom: 48px;
  border-bottom: 1px solid var(--border);
}
.footer-brand .brand-mark { font-size: 1.4rem; color: var(--accent); }
.footer-brand .brand-name { font-family: var(--font-display); font-size: 1.3rem; margin: 8px 0; color: var(--text); }
.footer-tag { color: var(--text-muted); max-width: 32ch; }
.footer-grid h2 {
  font-size: 0.78rem; font-family: var(--font-sans); font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.14em; color: var(--text); margin-bottom: 16px;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-grid a { color: var(--text-muted); font-size: 0.92rem; transition: color 0.2s; }
.footer-grid a:hover { color: var(--text); }
.footer-base {
  display: flex; justify-content: space-between; align-items: center; gap: 16px;
  padding-top: 24px; flex-wrap: wrap;
}
.footer-base p { font-size: 0.85rem; color: var(--text-dim); }
.footer-legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 20px; }
.footer-legal a { color: var(--text-dim); font-size: 0.85rem; }
.footer-legal a:hover { color: var(--text); }

/* TOAST */
.toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%) translateY(20px);
  background: var(--bg-elev-2); color: var(--text); padding: 12px 20px;
  border: 1px solid var(--border-strong); border-radius: 999px;
  font-size: 0.9rem; z-index: 100; box-shadow: var(--shadow);
  opacity: 0; pointer-events: none; transition: opacity 0.25s, transform 0.25s;
}
.toast.is-visible { opacity: 1; transform: translateX(-50%) translateY(0); }

/* RESPONSIVE */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { height: 440px; max-width: 560px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story--feature { grid-column: span 2; grid-row: auto; }
  .story--feature .story-art { aspect-ratio: 16/9; }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .deal--feature { grid-column: span 2; grid-row: auto; min-height: 360px; }
  .deal--wide { grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .primary-nav { display: none; }
  .section { padding: 64px 0; }
  .hero { padding: 48px 0 64px; }
  .hero-meta { grid-template-columns: 1fr 1fr; gap: 20px; }
  .values-grid { grid-template-columns: 1fr; gap: 20px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal--feature, .deal--wide { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story--feature { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .newsletter-form { grid-template-columns: 1fr; border-radius: var(--radius); padding: 16px; }
  .newsletter-form .btn { width: 100%; }
  .hero-visual { height: 380px; }
  .section-head { align-items: flex-start; }
}
@media (max-width: 480px) {
  .product-grid { grid-template-columns: 1fr; }
}

